const body = $input.first().json.body;
const channel = "email";
const requestKeys = ['user_id', 'conversation_id', 'channel', 'message', 'attachments', 'locale', 'request_id', 'permission_context'];
const permissionKeys = ['scopes', 'entitlements', 'consents'];
const attachmentKeys = ['attachment_id', 'name', 'media_type'];

const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isText = (value) => typeof value === 'string' && /\S/.test(value);
const hasOnly = (value, keys) => Object.keys(value).every((key) => keys.includes(key));
const isTextList = (value) => Array.isArray(value) && value.every(isText) && new Set(value).size === value.length;

function isPermissionContext(value) {
  return isObject(value) && hasOnly(value, permissionKeys)
    && Object.hasOwn(value, 'scopes')
    && Object.values(value).every(isTextList);
}

function isAttachment(value) {
  return isObject(value) && hasOnly(value, attachmentKeys)
    && Object.hasOwn(value, 'attachment_id')
    && Object.values(value).every(isText);
}

if (!isObject(body) || !hasOnly(body, requestKeys) || !requestKeys.every((key) => Object.hasOwn(body, key))
    || body.channel !== channel || !isText(body.user_id) || !isText(body.conversation_id)
    || !isText(body.request_id) || !isText(body.locale) || typeof body.message !== 'string'
    || !Array.isArray(body.attachments) || !body.attachments.every(isAttachment)
    || (!isText(body.message) && body.attachments.length === 0)
    || !isPermissionContext(body.permission_context)) {
  return [{ json: {
    http_status: 400,
    response: { status: 'invalid_request', request_id: null, channel, reply: "Заявката не отговаря на формата за този канал." },
  } }];
}

return [{ json: body }];

const request = $("Провери заявката").first().json;
const items = $input.all();
const result = items.length === 1 ? items[0].json : null;
const resultMatchesRequest = result && !Object.hasOwn(result, 'error')
  && result.request_id === request.request_id && result.channel === request.channel;

function response(status, http_status, reply) {
  return [{ json: {
    http_status,
    response: { status, request_id: request.request_id, channel: request.channel, reply },
  } }];
}

if (resultMatchesRequest && ['ok', 'needs_human'].includes(result.status)
    && typeof result.reply === 'string' && /\S/.test(result.reply)) {
  return response(result.status, 200, result.reply);
}
if (resultMatchesRequest && result.status === 'invalid_request') {
  return response('invalid_request', 400, "Заявката не отговаря на формата за този канал.");
}
return response('unavailable', 503, "Shark AI временно не може да обработи заявката.");
